def read_text(path):
    with open(path, "rb") as fh:
        data = fh.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    text = data.decode("utf-8-sig")
    return text.replace("\r\n", "\n").replace("\r", "\n")


def lines_of(path):
    return [ln for ln in read_text(path).split("\n") if ln.strip() != ""]


def to_epoch(dt):
    return int(dt.timestamp()) if dt.tzinfo else None


def local_to_epoch(naive, zone, fold):
    return int(naive.replace(tzinfo=zone, fold=fold).timestamp())


def iso_to_epoch(text):
    text = text.strip()
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
