        naive = datetime(int(year), int(month), int(day), hour, minute, second)
        abbr = get("Zone").upper()
        fold = 0 if abbr.endswith("DT") else 1
        out.append((get("Record"), get("Badge"), get("Punch").upper(),
                    local_to_epoch(naive, zone, fold)))
