    rates = {}
    for rec in read_csv_dicts(os.path.join(input_dir, "rates.csv")):
        rates.setdefault(rec["employee_id"], []).append(
            (date.fromisoformat(rec["effective_from"]), Fraction(Decimal(rec["hourly_rate"]))))
    for lst in rates.values():
        lst.sort()

    def night_minutes(in_epoch, out_epoch, zone):
        first = datetime.fromtimestamp(in_epoch, zone).date() - timedelta(days=1)
        last = datetime.fromtimestamp(out_epoch, zone).date()
        total = 0
        day = first
        while day <= last:
            lo = local_to_epoch(datetime(day.year, day.month, day.day, 22), zone, 0)
            nxt = day + timedelta(days=1)
            hi = local_to_epoch(datetime(nxt.year, nxt.month, nxt.day, 6), zone, 0)
            overlap = min(hi, out_epoch) - max(lo, in_epoch)
            if overlap > 0:
                total += overlap
            day = nxt
        return total // 60

    result = {}
    for emp in emp_home:
        items = sorted(by_emp.get(emp, []))
        kept = []
        for epoch, _rank, site, pid, direction in items:
            rounded = round_epoch(epoch, zones[site])
            if kept and kept[-1][4] == direction and epoch - kept[-1][5] <= 300:
                if start <= workday(rounded, emp) <= end:
                    exc["duplicates_dropped"] += 1
                continue
            kept.append((rounded, site, pid, 0, direction, epoch))
        shifts = []
        pending = None

        def close_open():
            if start <= workday(pending[0], emp) <= end:
                exc["open_shifts"] += 1

        for punch in kept:
            if punch[4] == "IN":
                if pending:
                    close_open()
                pending = punch
            else:
                if pending and punch[0] - pending[0] <= 16 * 3600:
                    shifts.append((pending, punch))
                    pending = None
                else:
                    if pending:
                        close_open()
                        pending = None
                    if start <= workday(punch[0], emp) <= end:
                        exc["orphan_outs"] += 1
        if pending:
            close_open()

        rows = []
        for in_p, out_p in shifts:
            day = workday(in_p[0], emp)
            if not (start <= day <= end):
                continue
            worked = max(0, (out_p[0] - in_p[0]) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(in_p[0], out_p[0], zones[in_p[1]]), paid)
            rows.append([in_p[0], day, paid, night])
        rows.sort(key=lambda r: r[0])
        day_total = {}
        week_total = {}
        total = Fraction(0)
        sums = [0, 0, 0]
        for in_epoch, day, paid, night in rows:
            before = day_total.get(day, 0)
            day_total[day] = before + paid
            daily_ot = max(0, before + paid - 480) - max(0, before - 480)
            non_daily = paid - daily_ot
            week = day - timedelta(days=day.weekday())
            wbefore = week_total.get(week, 0)
            week_total[week] = wbefore + non_daily
            weekly_ot = max(0, wbefore + non_daily - 2400) - max(0, wbefore - 2400)
            overtime = daily_ot + weekly_ot
            regular = paid - overtime
            rate = Fraction(0)
            for eff, value in rates.get(emp, []):
                if eff <= day:
                    rate = value
            total += rate * (regular + Fraction(3, 2) * overtime) / 60 + rate * Fraction(15, 100) * night / 60
            sums[0] += paid
            sums[1] += overtime
            sums[2] += night
        cents = int((total * 100 + Fraction(1, 2)) // 1)
        result[emp] = {"shifts": len(rows), "paid_minutes": sums[0], "overtime_minutes": sums[1],
                       "night_minutes": sums[2], "gross_cents": cents}

    totals = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0, "gross": 0}
    out_emps = {}
    for emp, rec in result.items():
        cents = rec.pop("gross_cents")
        rec["gross"] = "%d.%02d" % divmod(cents, 100)
        out_emps[emp] = rec
        for field in ("shifts", "paid_minutes", "overtime_minutes", "night_minutes"):
            totals[field] += rec[field]
        totals["gross"] += cents
    totals["gross"] = "%d.%02d" % divmod(totals["gross"], 100)
    summary = {"period": {"start": period["start"], "end": period["end"]},
               "employees": out_emps, "exceptions": exc, "totals": totals}
    with open(output_file, "w") as fh:
        json.dump(summary, fh, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
